import {evidenceReadiness,seasonalConsistency} from './evidence-readiness.mjs';
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderEvidence(evidence,supplement,lang,used=true){
 supplement=supplement??{};
 const ar=lang==='ar',say=(en,arabic)=>ar?arabic:en;const items=evidenceReadiness(evidence,supplement,used);
 const roles={DIRECT_INPUT:say('Used in calculations','مستخدم في الحسابات'),CONTEXT_ONLY:say('Context only','للسياق فقط'),REQUIRES_CONFIRMATION:say('Requires confirmation','يتطلب التحقق'),UNSUPPORTED:say('Unsupported','غير مدعوم')};
 const reasons={proposed_geometry:say('Selected proposed geometry; area is calculated, not farmer-verified.','حدود مقترحة مختارة؛ المساحة محسوبة وليست مؤكدة من المزارع.'),historical_grid:say('Historical grid estimates, not field sensors. Solar is displayed; Water Truth uses Tmax, Tmin and precipitation.','تقديرات شبكية تاريخية وليست أجهزة حقلية. الإشعاع للعرض؛ نموذج المياه يستخدم الحرارة والهطول.'),classification_not_confirmation:say('Mapped crop classification; not confirmed planting or the immediately preceding crop. No approved engine ID.','تصنيف خرائطي؛ ليس زراعة مؤكدة أو محصولاً سابقاً مؤكداً. لا يوجد معرّف محرك معتمد.'),no_soil_rule:say('Survey map attributes, not laboratory samples. No numerical soil rule consumes this record.','خصائص مسح خرائطي وليست عينات مختبرية. لا توجد قاعدة تربة عددية تستخدم هذا السجل.'),historical_summary:say('Historical season, not forecast. Not used in calculations.','موسم تاريخي وليس توقعاً. غير مستخدم في الحسابات.'),range_not_kc:say('Proposed profile; published water-use range is not an engine Kc or planting calendar.','ملف مقترح؛ نطاق استخدام المياه المنشور ليس معامل Kc أو تقويم زراعة للمحرك.'),missing_profile:say('No canonical profile for this engine crop.','لا يوجد ملف مرجعي لهذا المحصول في المحرك.'),malformed:say('Malformed or unsupported record; not used.','سجل غير صالح أو غير مدعوم؛ غير مستخدم.')};
 const metadata=i=>'<details><summary>'+say('Source, scope & readiness','المصدر والنطاق والجاهزية')+'</summary><dl>'+Object.entries({[say('Source','المصدر')]:i.source?.product??i.source?.url,[say('Spatial reference','المرجع المكاني')]:i.spatial,[say('Temporal coverage','التغطية الزمنية')]:i.temporal,[say('Units','الوحدات')]:i.units,[say('Missing values','القيم المفقودة')]:i.missing,[say('Verification','التحقق')]:i.verification,[say('Consumer','المستهلك')]:i.consumer??say('None','لا يوجد')}).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(typeof v==='object'?JSON.stringify(v):v)+'</dd>').join('')+'</dl></details>';
 const row=i=>'<article data-role="'+i.role+'"><span class="badge">'+roles[i.role]+'</span><p>'+esc(reasons[i.reason])+'</p>'+metadata(i)+'</article>';
 const history=items.filter(i=>i.kind==='history').map(i=>'<li><strong>'+esc(i.record.year)+' · '+esc(i.record.crop_label)+'</strong> · CDL '+esc(i.record.source_class_code)+row(i)+'</li>').join('');
 const soils=items.filter(i=>i.kind==='soil').map(i=>'<tr><td>'+esc(i.record.map_unit_id)+' / '+esc(i.record.component_name)+'</td><td>'+esc(i.record.depth_top_cm)+'–'+esc(i.record.depth_bottom_cm)+' cm</td><td>'+esc(i.record.texture)+'</td><td>'+esc(i.record.available_water_capacity_mm_per_mm)+' mm/mm</td><td>'+row(i)+'</td></tr>').join('');
 const seasons=items.filter(i=>i.kind==='seasonal').map(i=>'<article><strong>'+esc(i.record.period_start)+' — '+esc(i.record.period_end)+' · LST</strong><p>'+say('Precipitation','الهطول')+': '+esc(i.record.precip_total_mm)+' mm · '+say('Hot days','أيام حارة')+': '+esc(i.record.hot_days_count)+' (≥ '+esc(i.record.hot_day_threshold_c)+' °C) · '+esc(i.record.valid_days)+'/'+esc(i.record.expected_days)+'</p><p>'+say('Daily-series consistency','الاتساق مع الأيام')+': '+(seasonalConsistency(i.record,evidence.climateDaily)==='NOT_COMPARABLE'?say('Not comparable: loaded daily evidence is 2025; these seasons are 2023–2024.','غير قابل للمقارنة: البيانات اليومية المحملة لعام 2025 وهذه المواسم لعامي 2023–2024.'):esc(seasonalConsistency(i.record,evidence.climateDaily)))+'</p>'+row(i)+'</article>').join('');
 const mapping=(supplement?.compatibility?.compatibility??[]).map(m=>'<tr><td>'+esc(m.engineId)+'</td><td>'+esc(m.dbId)+'</td><td>'+esc(m.botanical)+'</td><td>'+say(m.status==='unmapped'?'No supported profile':m.engineId===null?'Outside engine catalog':'Proposed; not activated',m.status==='unmapped'?'لا يوجد ملف مدعوم':m.engineId===null?'خارج كتالوج المحرك':'مقترح؛ غير مفعل')+'</td></tr>').join('');
 const profiles=items.filter(i=>i.kind==='profile').map(i=>'<details><summary>'+esc(i.record.name)+' · '+esc(i.record.seasonal_water_use_mm_min)+'–'+esc(i.record.seasonal_water_use_mm_max)+' mm</summary><p>'+esc(i.record.scientific_name)+' · '+esc(i.record.plant_family)+'</p>'+row(i)+'</details>').join('');
 return '<section class="evidence-verification"><h3>'+say('Evidence & Verification','الأدلة والتحقق')+'</h3><p>'+say('Only selected geometry and daily climate feed the existing calculations. Crop history, soil and profile evidence below do not change plan outcomes. Missing farmer irrigation remains UNKNOWN.','الحدود المختارة والمناخ اليومي فقط يدخلان الحسابات الحالية. تاريخ المحاصيل والتربة والملفات أدناه لا تغير نتائج الخطط. ميزانية الري المفقودة تبقى غير معروفة.')+'</p><div class="status-counts">'+Object.keys(roles).map(r=>'<span class="badge">'+roles[r]+': '+items.filter(i=>i.role===r).length+'</span>').join('')+'</div>'+row(items[0])+row(items.find(i=>i.kind==='daily'))+Object.keys(supplement?.errors??{}).map(k=>'<p role="status" class="error">'+esc(k)+' · '+say('Unavailable or malformed. Reselect the demo to retry; no substitute evidence used.','غير متاح أو غير صالح. أعد اختيار الحقل للمحاولة؛ لم يستخدم دليل بديل.')+'</p>').join('')+'<details><summary>'+say('Mapped crop history · not farmer-confirmed','تاريخ المحاصيل الخرائطي · غير مؤكد من المزارع')+'</summary><ol>'+history+'</ol></details><details><summary>'+say('Soil horizons · 26 separate survey records','طبقات التربة · 26 سجل مسح منفصل')+'</summary><div class="evidence-table"><table><thead><tr>'+[say('Map unit / component','وحدة الخريطة / المكوّن'),say('Depth','العمق'),say('Texture','القوام'),'AWC',say('Readiness','الجاهزية')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+soils+'</tbody></table></div></details><details><summary>'+say('Historical seasonal climate','المناخ الموسمي التاريخي')+'</summary>'+seasons+'</details><details><summary>'+say('Crop compatibility · no approved engine mapping','توافق المحاصيل · لا ربط معتمد بالمحرك')+'</summary><p>'+say('Chickpea has an exact slug but no approved water-model contract; wheat season/type is unresolved. No mapping is activated.','للحمص معرّف مطابق لكن لا عقد معتمد لنموذج المياه؛ نوع وموسم القمح غير محسومين. لا يتم تفعيل أي ربط.')+'</p><div class="evidence-table"><table><tbody>'+mapping+'</tbody></table></div>'+profiles+'</details></section>';
}
